/* ==================================================
 * Quaestio (QA+QB+QC): selectores CSS-similes super arbores
 * commissas (consilium: project-specs/silva-quaestio-design.md,
 * DECISUS). Tags = tituli generum registri (kebab); combinatores
 * spatium (descendens) et > (filius); unio virgula; * universalis.
 * Tag/locus/pseudo ignotum aut selector malformatus = NULL + causa
 * (fractura CLARA). Ambigua: descensus per lectionem canonicam
 * solam (:lectiones aperit omnes); involucrum ipsum congruibile
 * (tag "ambiguus" aut :ambiguum); nodi ERROR congruibiles (tag
 * "error"). Arbores COMMISSAE exspectantur (pater fixus).
 * ================================================== */

typedef struct SilvaQuaestio SilvaQuaestio;  /* compilata (opaca) */

/* Tabula pseudo-classium usoris (QC, opaca) - impletur ANTE
 * compilationem (pseudo ignotum in compilatione = fractura) */
typedef struct SilvaQuaestioPseudoRegistrum
    SilvaQuaestioPseudoRegistrum;

/* Functio pseudo-classis usoris: nodus sub probatione + argumentum
 * (chorda vacua si sine parenthesibus) + datum registrationis.
 * Non-zephyrum = congruit. */
typedef int (*SilvaQuaestioPseudoFunctio)(const SilvaNodus* nodus,
    SilvaChorda argumentum, void* datum);

/* Captura ligata (QB): gradus catenae congruentis cum $nomine -
 * gradus OMNES ligantur, non subiectum solum */
typedef struct SilvaQuaestioCaptura {
    SilvaChorda       titulus;
    const SilvaNodus* nodus;
} SilvaQuaestioCaptura;

typedef struct SilvaQuaestioResultatum {
    const SilvaNodus* nodus;    /* subiectum congruens */
    SilvaXar*         capturae; /* SilvaQuaestioCaptura (valore);
                                 * NULL = catena sine capturis */
} SilvaQuaestioResultatum;

/* Selector -> quaestio compilata (reusabilis trans arbores).
 * Superficies QA+QB+QC: tags, *, spatium, >, virgula, +/~
 * (fratres), [locus op "valor"] (= ^= $= *= et exsistentia; locus
 * PER GENUS; compositum cum tag = validatio compilationis), $nomen
 * (capturae), pseudo-classes: :primus/:ultimus (sine lista
 * continente = filius solus = AMBO), :habet(sel) (descendens
 * congruens - catena intra subarborem confinata), :non(sel),
 * :vocat(f)/:definit(x)/:utitur(x)/:reddit (semantici - CONTINET;
 * genera per nomen, grammaticae absens = numquam congruit),
 * :ambiguum, :lectiones, :sumptus/:omissus. NULL + *causa_out
 * (litterae staticae; NULL licet) si malformatus aut nomen
 * ignotum. */
SilvaQuaestio* silva_quaestio_compilare(SilvaPiscina* piscina,
    const SilvaRegistrumCoctum* tabularium, const char* selector,
    const char** causa_out);

/* Ut compilare, sed pseudo-classes usoris ex tabula data agnoscit
 * (registro NULL = nativae solae; functiones in quaestionem
 * copiantur). */
SilvaQuaestio* silva_quaestio_compilare_cum_registro(
    SilvaPiscina* piscina, const SilvaRegistrumCoctum* tabularium,
    const SilvaQuaestioPseudoRegistrum* registro,
    const char* selector, const char** causa_out);

/* Tabulam pseudo-classium vacuam creare. */
SilvaQuaestioPseudoRegistrum* silva_quaestio_registrum_creare(
    SilvaPiscina* piscina);

/* Pseudo-classem usoris registrare. Zephyrum: argumentum NULL,
 * titulus vacuus/litteris non-tag, aut nomen nativum obumbraret.
 * Titulus idem iterum = renovatio (non-zephyrum). */
int silva_quaestio_registrare(
    SilvaQuaestioPseudoRegistrum* registro, const char* titulus,
    SilvaQuaestioPseudoFunctio functio, void* datum);

/* Omnes nodi congruentes sub radice (commissio->radix directa).
 * SilvaXar de SilvaQuaestioResultatum (valore) in piscinam. */
SilvaXar* silva_quaestio_exsequi(const SilvaQuaestio* quaestio,
    SilvaValor radix, SilvaPiscina* piscina);

/* Nodusne unus catenae alicui congruit (maiores per patrem)? */
int silva_quaestio_congruit(const SilvaQuaestio* quaestio,
    const SilvaNodus* nodus);

/* ==================================================
 * Quaestiones nominatae: bibliotheca selectorum commissa
 * (silva/quaestiones.stml; parcum 01KXPV9FPK, 2026-07-31).
 * Entria divitia: titulus + gradus (oculi|invarians) + selector
 * cum $parametris declaratis + causa obligatoria. Validatio in
 * legere - plagula tota valida aut NULL + culpa nominata (selector
 * compilatur per specimen, parametra <-> $loci utrimque, invarians
 * = zero parametra, tituli unici). Substitutio contextu
 * discriminata: valores attributorum citati + argumentum pseudo
 * integrum ($capturae post tagum intactae). Invarians = selector
 * qui ZERO congruentias reddere debet (custodia structuralis;
 * percursus = ./silva/quaestio.sh -invariantia, oculi solum).
 * ================================================== */

typedef enum {
    SILVA_QUAESTIONES_OCULI = 0,  /* relatio - numquam porta */
    SILVA_QUAESTIONES_INVARIANS   /* zero congruentiae = TENET */
} SilvaQuaestionesGradus;

/* Quaestio nominata: unum entrium bibliothecae (lectum, validatum) */
typedef struct SilvaQuaestioNominata {
    SilvaChorda titulus;
    int         gradus;      /* SilvaQuaestionesGradus */
    SilvaChorda selector;    /* textus crudus cum $parametris */
    SilvaXar*   parametra;   /* SilvaChorda (valore) - declarata */
    SilvaChorda causa;
} SilvaQuaestioNominata;

/* Argumentum pro parare: par titulus->valor */
typedef struct SilvaQuaestionesArgumentum {
    SilvaChorda titulus;
    SilvaChorda valor;
} SilvaQuaestionesArgumentum;

/* Bibliotheca lecta. tabularium/registro hic servantur - registro
 * per compilationes posteriores (parare) legitur, ergo bibliothecam
 * supervivere debet. */
typedef struct SilvaQuaestiones {
    SilvaXar*                              nominatae;
    const SilvaRegistrumCoctum*            tabularium;
    const SilvaQuaestioPseudoRegistrum*    registro;
} SilvaQuaestiones;

/* Bibliothecam ex chorda legere et TOTAM validare. NULL +
 * *culpa_out (in piscinam formata, entrium nominans) in fractura
 * QUALIBET. registro NULL = pseudo nativae solae. */
SilvaQuaestiones* silva_quaestiones_legere(SilvaPiscina* piscina,
    const SilvaRegistrumCoctum* tabularium,
    const SilvaQuaestioPseudoRegistrum* registro,
    SilvaChorda fons, SilvaChorda* culpa_out);

unsigned int silva_quaestiones_numerus(
    const SilvaQuaestiones* bibliotheca);

/* Ad indicem; NULL = extra fines */
const SilvaQuaestioNominata* silva_quaestiones_ad_indicem(
    const SilvaQuaestiones* bibliotheca, unsigned int index);

/* Per titulum; NULL = absens */
const SilvaQuaestioNominata* silva_quaestiones_invenire(
    const SilvaQuaestiones* bibliotheca, const char* titulus);

/* Argumenta in selectorem texere et compilare. argumenta = series
 * PLANA (monstrator + numerus; NULL/0 = nulla) - non Xar, ut
 * hospites (quibus Xar legendus solum est) eam aedificare possint.
 * Fracturae nominatae: argumentum absens/ignotum/iteratum, valor
 * illicitus ('"' '(' ')' vetiti), compilatio. Fructus reusabilis
 * trans arbores. */
SilvaQuaestio* silva_quaestiones_parare(SilvaPiscina* piscina,
    const SilvaQuaestiones* bibliotheca,
    const SilvaQuaestioNominata* nominata,
    const SilvaQuaestionesArgumentum* argumenta,
    unsigned int numerus_argumentorum, SilvaChorda* culpa_out);

/* ==================================================
 * Semantica C89 (M0a): typi + scopi + forma + index — tabulae
 * parallelae super arbores commissas (consilium:
 * project-specs/silva-semantica-design.md DECISUS). Ansa typi =
 * monstrator UNUS: derivati internantur (aequalitas monstratorum
 * EST identitas), tags nominales. Forma arm64 LP64 Apple
 * (long double = 8; long long = extensio recepta — s64!),
 * VERIFICATA contra clang per haruspicem (4,801 assertiones).
 * Diagnostica venenata: TYPUS_C89_ERROR absorbet sine cascata.
 * ================================================== */

typedef enum {
    TYPUS_C89_PRIMITIVUS = 0,
    TYPUS_C89_MONSTRATOR,
    TYPUS_C89_ACIES,
    TYPUS_C89_FUNCTIO,
    TYPUS_C89_STRUCTURA,
    TYPUS_C89_UNIO,
    TYPUS_C89_ENUMERATUS,
    TYPUS_C89_QUALIFICATUS,
    TYPUS_C89_ERROR
} TypusC89Genus;

typedef enum {
    PRIMITIVUM_VACUUM = 0,
    PRIMITIVUM_CHARACTER,
    PRIMITIVUM_CHARACTER_SIGNATUM,
    PRIMITIVUM_CHARACTER_INSIGNATUM,
    PRIMITIVUM_BREVIS,
    PRIMITIVUM_BREVIS_INSIGNATUM,
    PRIMITIVUM_INTEGER,
    PRIMITIVUM_INTEGER_INSIGNATUM,
    PRIMITIVUM_LONGUS,
    PRIMITIVUM_LONGUS_INSIGNATUM,
    PRIMITIVUM_LONGUS_LONGUS,
    PRIMITIVUM_LONGUS_LONGUS_INSIGNATUM,
    PRIMITIVUM_FLUITANS,
    PRIMITIVUM_DUPLEX,
    PRIMITIVUM_DUPLEX_LONGUS,
    PRIMITIVUM_NUMERUS
} TypusC89Primitivum;

#define QUALIS_CONSTANS   1
#define QUALIS_VOLATILIS  2

typedef struct TypusC89 TypusC89;

typedef struct {
    SilvaChorda  titulus;      /* copia; mensura 0 = anonymum */
    TypusC89*    typus;
    unsigned int offset;       /* octeti; a forma computatus */
    int          est_campus;   /* bitfield (forma tag parcata) */
} TypusC89Membrum;

struct TypusC89 {
    int genus;                 /* TypusC89Genus */
    int ex_systemate;          /* provenientia (haruspex) */

    int forma_computata;
    int in_computatione;
    unsigned int magnitudo_octetorum;
    unsigned int ordinatio;

    union {
        int primitivum;        /* TypusC89Primitivum */
        struct {
            TypusC89* internum;
        } monstrator;
        struct {
            TypusC89* elementum;
            int       numerus;      /* -1 = incompleta */
        } acies;
        struct {
            TypusC89*    reditus;
            TypusC89**   parametra;
            unsigned int numerus_parametrorum;
            int          est_variadica;
            int          est_prototypata;
        } functio;
        struct {
            SilvaChorda       titulus;
            int               completa;
            TypusC89Membrum*  membra;
            unsigned int      numerus_membrorum;
            const SilvaNodus* declarans;
            int               habet_campos;
        } tag;
        struct {
            SilvaChorda       titulus;
            int               completa;
            const SilvaNodus* declarans;
        } enumeratus;
        struct {
            TypusC89*    internum;
            unsigned int quales;
        } qualificatus;
    } datum;
};

typedef enum {
    SYMBOLUM_VARIABILE = 0,
    SYMBOLUM_FUNCTIO,
    SYMBOLUM_TYPEDEF,
    SYMBOLUM_CONSTANS,
    SYMBOLUM_PARAMETRUM
} SemanticaSymbolumGenus;

#define REPOSITIO_STATICA   1
#define REPOSITIO_EXTERNA   2
#define REPOSITIO_AUTOMATA  4
#define REPOSITIO_REGISTRI  8

/* SYMBOLA = REGISTRATIONES, NON ENTIA (acta sunt fructus):
 * declaratio quaeque symbolum PROPRIUM registrat - prototypus +
 * definitio eiusdem functionis = symbola DUO, quodque cum declarans
 * suo. Enumeratio (symbolum_per_indicem) OMNIA reddit; consumptor
 * qui "ens" vult registrationes plicet, definitione praelata -
 * probatio: silva_c89_definitio_functionis_corpus(declarans)
 * generis alieni SILVA_VALOR_NIHIL reddit. */
typedef struct {
    int               genus;        /* SemanticaSymbolumGenus */
    SilvaChorda       titulus;
    TypusC89*         typus;
    long long         valor;        /* CONSTANS solum */
    unsigned int      repositio;
    unsigned int      profunditas;  /* 0 = scopus fili */
    int               ex_systemate;
    int               est_implicitum; /* extern int implicitum
                                       * synthetizatum (M0b C) */
    const SilvaNodus* declarans;    /* implicitis: sedes vocationis */
    SilvaToken*       lexema;
    int               usus;         /* resolutio symbolum invenit
                                     * (codices 69/70) */
} SemanticaSymbolum;

/* Examen (M4a chunk A): severitas + codices diagnosticorum.
 * INFRA = lacuna instrumentorum, numquam iudicium (verdicta ordines
 * INFRA excludunt, ut provisionales). */
typedef enum {
    EXAMEN_VIOLATIO = 0,
    EXAMEN_SUSPECTUM,
    EXAMEN_DOMESTICUM,
    EXAMEN_INFRA
} ExamenSeveritas;

/* Codex stabilis per nuntium - ordo tabulae internae; NE INSERE -
 * adde ante NUMERUS (stabilitas pro vecte differentiali). */
typedef enum {
    EXAMEN_CODEX_REDECLARATIO_GENERIS = 0,
    EXAMEN_CODEX_TAG_SINE_CORPORE,
    EXAMEN_CODEX_ENUMERATIO_SINE_CORPORE,
    EXAMEN_CODEX_ENUMERATOR_NON_CONSTANS,
    EXAMEN_CODEX_TYPUS_NOMINATUS_IGNOTUS,   /* INFRA: LEXICON_DEEST */
    EXAMEN_CODEX_ERROR_IN_SPECIFICATORIBUS,
    EXAMEN_CODEX_SPECIFICATORES_MIXTI,
    EXAMEN_CODEX_MULTISET_PRIMITIVORUM,
    EXAMEN_CODEX_MENSURA_ACIEI,
    EXAMEN_CODEX_ERROR_IN_DECLARATORE,
    EXAMEN_CODEX_GENUS_DECLARATORIS,        /* INFRA: cautela */
    EXAMEN_CODEX_SPECIES_TYPI_EXSPECTATA,
    EXAMEN_CODEX_DECLARATIONES_KR,          /* INFRA: parca */
    EXAMEN_CODEX_CYCLUS_FORMAE,
    EXAMEN_CODEX_FORMA_ACIEI_INCOMPLETAE,
    EXAMEN_CODEX_FORMA_FUNCTIONIS,
    EXAMEN_CODEX_CAMPI_PARCATI,             /* INFRA: parca */
    EXAMEN_CODEX_CHORDA_LATA,               /* INFRA: parca */
    EXAMEN_CODEX_FUGA_INVALIDA,
    EXAMEN_CODEX_LITTERALE_INVALIDUM,
    EXAMEN_CODEX_IDENTIFICATOR_IGNOTUS,
    EXAMEN_CODEX_TYPEDEF_IN_EXPRESSIONE,
    EXAMEN_CODEX_TYPEDEF_VOCATUM,
    EXAMEN_CODEX_OPERANDUM_UNARII,
    EXAMEN_CODEX_OPERANDUM_TILDE,
    EXAMEN_CODEX_DEIECTIO_NON_MONSTRATORIS,
    EXAMEN_CODEX_CREMENTUM_NON_SCALARE,
    EXAMEN_CODEX_MULTIPLICATIVA,
    EXAMEN_CODEX_OPERANDA_NON_INTEGRALIA,
    EXAMEN_CODEX_ADDITIVA_INCOMPATIBILIA,
    EXAMEN_CODEX_SUBTRACTIONIS_INCOMPATIBILIA,
    EXAMEN_CODEX_MOTUS_NON_INTEGRALIA,
    EXAMEN_CODEX_COMPARATIO_INCOMPATIBILIUM,
    EXAMEN_CODEX_BRACCHIA_TERNARII,
    EXAMEN_CODEX_SUBSCRIPTIO_NON_MONSTRATORIS,
    EXAMEN_CODEX_VOCATUS_NON_FUNCTIO,
    EXAMEN_CODEX_SAGITTA_NON_MONSTRATORIS,
    EXAMEN_CODEX_ACCESSUS_NON_STRUCTURAE,
    EXAMEN_CODEX_ACCESSUS_INCOMPLETAE,
    EXAMEN_CODEX_MEMBRUM_IGNOTUM,
    EXAMEN_CODEX_ELISIO_UNCORUM,            /* INFRA: parca */
    /* chunk B (relatio compatibilitatis) - flagrant a chunk C */
    EXAMEN_CODEX_ASSIGNATIO_INCOMPATIBILIS,
    EXAMEN_CODEX_MONSTRATORES_INCOMPATIBILES,
    EXAMEN_CODEX_QUALES_ABIECTI,
    EXAMEN_CODEX_MONSTRATOR_INTEGER,
    /* chunk C (sedes) */
    EXAMEN_CODEX_ASSIGNATIO_NON_LOCUS,
    EXAMEN_CODEX_LOCUS_IMMUTABILIS,
    EXAMEN_CODEX_NUMERUS_ARGUMENTORUM,
    EXAMEN_CODEX_REDDE_CUM_VALORE_IN_VACUO,
    EXAMEN_CODEX_REDDE_SINE_VALORE,     /* SUSPECTUM: legale C89 */
    EXAMEN_CODEX_CONDICIO_NON_SCALARIS,
    EXAMEN_CODEX_VOCATIO_IMPLICITA,     /* SUSPECTUM: est_implicitum */
    EXAMEN_CODEX_REDECLARATIO_INCOMPATIBILIS,
    /* macro domesticum in capite alieno (vendor) expansum -
     * SUSPECTUM; causa in piscina structa (nominat omnia) */
    EXAMEN_CODEX_MACRO_DOMESTICUM_IN_ALIENO,
    /* conversio signi implicita valores non servans (murus
     * i32-insignatus) - DOMESTICUM (legale C89, vexilla domus
     * reiciunt); causa in piscina structa (typos ambos nominat) */
    EXAMEN_CODEX_CONVERSIO_SIGNI,
    /* gradus severi (TOLERA): analysis stricta supra oraculum -
     * suppressibilis commentario "TOLERA CONVERSIO_SIGNI_SEVERA:
     * causa" (linea eadem/praecedens, causa obligatoria); IRRITUM
     * = suppressio quae nihil absorbet aut sine causa */
    EXAMEN_CODEX_CONVERSIO_SIGNI_SEVERA,
    EXAMEN_CODEX_TOLERA_IRRITUM,
    /* comparationes (phasis II): SIGNORUM = paritas -Wsign-compare;
     * VANA = tautologica contra zephyrum (typus communis insignatus
     * aut intervallum sanum; per macra videt - ZEPHYRUM),
     * TOLERA-suppressibilis */
    EXAMEN_CODEX_COMPARATIO_SIGNORUM,
    EXAMEN_CODEX_COMPARATIO_VANA,
    /* CHORDA_NUDA = chorda.datum ad lectorem C sine limite (chorda
     * non terminatur NUL - regula domus); TOLERA-suppressibilis */
    EXAMEN_CODEX_CHORDA_NUDA,
    /* SIGNUM_FORMATI = %u cum argumento signato (clang tacet;
     * directio %d-cum-insignato DECRETO exempta - involutio
     * negativa visibilis diagnostica); TOLERA-suppressibilis */
    EXAMEN_CODEX_SIGNUM_FORMATI,
    /* SENTINELLA_INSIGNATA = redde constantis negativae (per casus)
     * e functione insignata; TOLERA-suppressibilis */
    EXAMEN_CODEX_SENTINELLA_INSIGNATA,
    /* COMPARATIO_DEGRADATA = X <= 0 / 0 >= X insignati (== 0 fit);
     * DORMIT usque ad analysim fluxus (CFG gradus 2) */
    EXAMEN_CODEX_COMPARATIO_DEGRADATA,
    /* FLUXUS-0: SEMITA_SINE_REDDITU = paritas -Wreturn-type (margo
     * CADIT fonte attingibili, functio non vacua); CASUS_LAPSUS /
     * SENTENTIA_INATTINGIBILIS tractibus posterioribus reservati;
     * FRANGE_EXTRA_CONTEXTUM / SALTA_AD_TITULUM_IGNOTUM = VIOLATIO
     * (paritas erroris clang) */
    EXAMEN_CODEX_SEMITA_SINE_REDDITU,
    EXAMEN_CODEX_CASUS_LAPSUS,
    EXAMEN_CODEX_SENTENTIA_INATTINGIBILIS,
    EXAMEN_CODEX_FRANGE_EXTRA_CONTEXTUM,
    EXAMEN_CODEX_SALTA_AD_TITULUM_IGNOTUM,
    /* ANGUSTATIO = latitudo angustior eiusdem signi (paritas
     * -Wconversion directione latitudinis); VARIABILIS/PARAMETRUM
     * INUTILE = paritas -Wunused-variable/-parameter */
    EXAMEN_CODEX_ANGUSTATIO,
    EXAMEN_CODEX_VARIABILIS_INUTILIS,
    EXAMEN_CODEX_PARAMETRUM_INUTILE,
    EXAMEN_CODEX_LECTIO_ININITIATA,
    EXAMEN_CODEX_ININITIATA_QUANDOCUMQUE,
    EXAMEN_CODEX_ININITIATA_FORSITAN,
    EXAMEN_CODEX_ANNOTATIO_MALFORMATA,
    EXAMEN_CODEX_NID_DUPLICATUM,
    EXAMEN_CODEX_IDENTITAS_INVALIDA,
    EXAMEN_CODEX_CONTRACTUS_VIOLATUS,
    EXAMEN_CODEX_CONTRACTUS_STALUS,
    EXAMEN_CODEX_CONTRACTUS_ABSENS,
    EXAMEN_CODEX_SUBTRACTIO_COMPARATA,
    EXAMEN_CODEX_CONTRACTUS_INTERVALLI_VIOLATUS,
    EXAMEN_CODEX_SIGNATUM_COMMIXTUM,
    EXAMEN_CODEX_IDENTIFICATOR_RESERVATUS,
    EXAMEN_CODEX_IDENTIFICATOR_ALIENUS,
    EXAMEN_CODEX_POSTULATA_DESUNT,
    EXAMEN_CODEX_VERNACULUM_ADHIBITUM,
    EXAMEN_CODEX_OBSOLETUM_ADHIBITUM,
    EXAMEN_CODEX_PORTABILE_VIOLATUM,
    EXAMEN_CODEX_NUMERUS
} ExamenCodex;

/* Licentia assignationis (iudicium directionale 6.3.16.1) */
typedef enum {
    EXAMEN_LICET = 0,          /* nulla conversio (typi identici) */
    EXAMEN_LICET_CONVERSIO,    /* licita cum conversione ad finem */
    EXAMEN_VETITUM             /* violatio - codex_out dicit quae */
} ExamenLicentia;

/* Diagnosticum v2 (M4a chunk A): positio materializata tempore
 * additionis; vita viae = vita parsurae ambulationis. */
typedef struct {
    const SilvaNodus* nodus;        /* NULL licet */
    const char*       causa;        /* litterae staticae (ex tabula);
                                     * MACRO_DOMESTICUM_IN_ALIENO in
                                     * piscina struit (nominat) */
    int               codex;        /* ExamenCodex */
    int               severitas;    /* ExamenSeveritas */
    int               provisionale; /* sub AMBIGUO retento */
    SilvaChorda       via;          /* radicis; vacua si ignota */
    unsigned int      linea;        /* 1-basata; 0 si ignota */
    unsigned int      columna;      /* 1-basata; 0 si ignota */
    unsigned int      longitudo;    /* octeti lexematis primi
                                     * (radicis); 0 si ignota */
    int               fons_index;   /* fons radicis (catena:
                                     * silva_inclusionis_catena_
                                     * scribere); -1 ignotus */
    const SilvaNodus* socius;       /* sedes cognata; NULL licet */
} SemanticaDiagnosticum;

typedef struct SilvaSemantica SilvaSemantica;   /* opaca */

/* Analysis totius fili super arborem commissam (ordine fontis,
 * registra-ante-usum; rami sumpti; canonica ambiguorum; K&R
 * parca). Numquam ruit. */
SilvaSemantica* silva_c89_semantica_analysare(SilvaPiscina* piscina,
    const SilvaParsura* parsura);

/* Ut supra, symbola systematis prius harvestata (systema =
 * parsura systema_c89.h; NULL licet = simplex) */
SilvaSemantica* silva_c89_semantica_analysare_cum_systemate(
    SilvaPiscina* piscina, const SilvaParsura* parsura,
    const SilvaParsura* systema);

/* Symbola in oraculum fundere (typedef -> typi; cetera ->
 * NON-typi, oraculum trivalens) - praeoneratio et clausura */
unsigned int silva_c89_semantica_oraculum_augere(
    const SilvaSemantica* sem, SilvaOraculum* oraculum);

/* Quot ambigua retenta adhuc INDECISA (voca
 * silva_oraculum_responsa_vacare ante pro statu recenti) */
unsigned int silva_c89_ambigua_indecisa_numerare(
    const SilvaCommissio* commissio, const SilvaOraculum* oraculum);

/* Quaestio symboli (a scopo fili post analysem) */
SemanticaSymbolum* silva_c89_symbolum_invenire(SilvaSemantica* sem,
    SilvaChorda titulus);

/* Index: omnia symbola creata (cum profunditate) - saltuarius
 * saltus typorum = consumptor primus nominatus */
unsigned int silva_c89_symbola_numerus(const SilvaSemantica* sem);
const SemanticaSymbolum* silva_c89_symbolum_per_indicem(
    const SilvaSemantica* sem, unsigned int index);

/* Relatio compatibilitatis C89 6.1.2.6 (examen chunk B) - pura,
 * symmetrica; ERROR absorbet; tags nominales; enum <-> int. */
int silva_c89_typi_compatibiles(TypusC89* a, TypusC89* b);

/* Iudicium directionale assignationis (6.3.16.1; etiam initiator
 * scalaris/argumentum prototypatum/redde). Reddit ExamenLicentia;
 * sub VETITO codex_out (NULL licet) codicem violationis fert. */
int silva_c89_assignationem_iudicare(SilvaSemantica* sem,
    const SilvaNodus* nodus_valoris, TypusC89* finis,
    TypusC89* valoris, int* codex_out);

/* Tabula codicum quaerenda (causa + severitas per codicem) */
const char* silva_c89_codicis_causa(int codex);
int silva_c89_codicis_severitas(int codex);

unsigned int silva_c89_diagnostica_numerus(
    const SilvaSemantica* sem);
const SemanticaDiagnosticum* silva_c89_diagnosticum_per_indicem(
    const SilvaSemantica* sem, unsigned int index);

/* Forma pigra: VERUM si magnitudo/ordinatio (et offsets) validae */
int silva_c89_formam_computare(SilvaSemantica* sem,
    TypusC89* typus);

/* Singuli primitivi (aequalitas monstratorum = identitas) */
TypusC89* silva_c89_typus_primitivum(SilvaSemantica* sem,
    int primitivum);

/* ==================================================
 * Typatio expressionum (M0b) - tabula parallela nodus ->
 * {typus naturalis, typus conversus}: naturalis = typus proprius
 * SINE lapsu (acies manet acies - sizeof rectum); conversus =
 * conversio scopo applicata (lapsus/UAC/assignatio/argumentum/
 * reditus) aut NIHIL. Quaestiones canonicae-consciae (involucrum
 * ambiguum aut lectionem des, idem redditur). NB typatio RELATIVA
 * CANONICAE est: post recanonicare analysim NOVAM fac (percursus
 * bis analysat). Contractus demissionis officinae.
 * ================================================== */

const TypusC89* silva_c89_typus_expressionis(
    const SilvaSemantica* sem, const SilvaNodus* nodus);
/* NIHIL = nulla conversio scopo applicata */
const TypusC89* silva_c89_conversio_expressionis(
    const SilvaSemantica* sem, const SilvaNodus* nodus);
unsigned int silva_c89_typationes_numerus(
    const SilvaSemantica* sem);

/* Redditor typorum (LEGATUS chunk 0): typus -> textus latinus
 * C-stili in buffer datum (NUL appenso). Functiones = signatura
 * "reditus(parametra)"; acies = "T[n]" / "T[]"; aggregata anonyma
 * = "<anonyma>" (typedef tag anonymum baptizat titulo suo). Redde
 * octetos scriptos; 0 = irreddibilis (error / spatium deficiens)
 * - buffer tunc vacuus. */
unsigned int silva_c89_typum_scribere(const TypusC89* t,
    char* buffer, unsigned int capacitas);

/* ==================================================
 * Exporta demissionis (M1a Chunk A; officina-m1-spec §II)
 * ================================================== */

/* Symbolum sedis usus (folium-identificator aut vocatus
 * vocationis, etiam implicitus). Canonicae-conscia et RELATIVA
 * CANONICAE ut typatio. NIHIL si non resoluta. */
const SemanticaSymbolum* silva_c89_symbolum_nodi(
    const SilvaSemantica* sem, const SilvaNodus* nodus);
unsigned int silva_c89_nexus_numerus(const SilvaSemantica* sem);

/* Expressio constans integralis C89 -> valor (VERUM si constans).
 * folium-integer/-character, constantes enumerorum, unarium,
 * binarium, ternarius, conversio, magnitudo-typi/-expressionis. */
int silva_c89_constans_aestimare(SilvaSemantica* sem,
    const SilvaNodus* expressio, long long* valor_out);

/* Octeti chordae litteralis DECODATI (fugae solutae, fragmenta
 * adiacentia coniuncta) in piscinam datam. SINE nullo terminali -
 * materia data (acies.numerus = octeti + 1; nullum ex typo).
 * FALSUM: L-chorda (parca), fuga invalida, nodus non chorda. */
int silva_c89_chorda_decodere(SilvaPiscina* piscina,
    const SilvaNodus* nodus, SilvaChorda* octeti_out);

/* ==================================================
 * Annotationes STML (stratum identitatis et intentionis)
 *
 * Commentarium cuius contentum primum non-spatium tag STML apertum
 * est ANNOTATIO est - collectum, purgatum (decoratio ' * ' exuta),
 * per stml_legere parsatum, unitati supremae affixum. Ancoratum
 * quod parsare nequit in fructu MANET (parsata falsum + positiones)
 * - numquam tacite prosa. Subcopia stml LEGENDI hic exposita;
 * scriptio/mutatio stml intra silva.c manent.
 * ================================================== */

/* internamentum praenuntiatum (opacum; creare + tradere) */
typedef struct SilvaInternamentumChorda SilvaInternamentumChorda;

SilvaInternamentumChorda* silva_internamentum_creare(
    SilvaPiscina* piscina);

typedef enum {
    STML_NODUS_DOCUMENTUM   = 1,
    STML_NODUS_ELEMENTUM    = 2,
    STML_NODUS_TEXTUS       = 3,
    STML_NODUS_COMMENTUM    = 4,
    STML_NODUS_PROCESSIO    = 5,
    STML_NODUS_DOCTYPE      = 6,
    STML_NODUS_TRANSCLUSIO  = 7
} SilvaStmlNodusGenus;

typedef enum {
    STML_CAPTIO_NIHIL       = 0,
    STML_CAPTIO_ANTE        = 1,
    STML_CAPTIO_RETRO       = 2,
    STML_CAPTIO_FARCIMEN    = 3
} SilvaStmlCaptioDirectio;

typedef enum {
    STML_SUCCESSUS                   = 0,
    STML_ERROR_MEMORIA               = 1,
    STML_ERROR_SYNTAXIS              = 2,
    STML_ERROR_TAG_NON_CLAUSUM       = 3,
    STML_ERROR_TAG_IMPROPRIE        = 4,
    STML_ERROR_ATTRIBUTUM            = 5,
    STML_ERROR_VACUUM_INPUT          = 6,
    STML_ERROR_CAPTIO                = 7
} SilvaStmlStatus;

typedef struct {
    SilvaChorda* titulus;    /* internata */
    SilvaChorda* valor;      /* internata ("true" pro boolean) */
} SilvaStmlAttributum;

typedef struct SilvaStmlNodus {
    SilvaStmlNodusGenus     genus;
    SilvaChorda*            titulus;     /* elementorum */
    SilvaChorda*            valor;       /* textus/commenti/PI */
    SilvaXar*               attributa;   /* SilvaStmlAttributum */
    SilvaXar*               liberi;      /* SilvaStmlNodus* */
    struct SilvaStmlNodus*  parens;
    int                     crudus;
    SilvaStmlCaptioDirectio captio_directio;
    unsigned int            captio_numerus;
    int                     clausura_anonyma; /* clausum per </> -
                                               * scriptor formam
                                               * authoris servat */
    int                     fragmentum;
    SilvaChorda*            fragmentum_id;
} SilvaStmlNodus;

typedef struct {
    int              successus;
    SilvaStmlNodus*  radix;
    SilvaStmlNodus*  elementum_radix;
    SilvaStmlStatus  status;
    unsigned int     linea_erroris;
    unsigned int     columna_erroris;
    SilvaChorda      error;
} SilvaStmlResultus;

SilvaStmlResultus silva_stml_legere(SilvaChorda input,
    SilvaPiscina* piscina, SilvaInternamentumChorda* intern);
SilvaStmlNodus* silva_stml_invenire_liberum(SilvaStmlNodus* nodus,
    const char* titulus);
SilvaChorda* silva_stml_attributum_capere(SilvaStmlNodus* nodus,
    const char* titulus);
int silva_stml_attributum_habet(SilvaStmlNodus* nodus,
    const char* titulus);
SilvaChorda silva_stml_textus_internus(SilvaStmlNodus* nodus,
    SilvaPiscina* piscina);
unsigned int silva_stml_numerus_liberorum(SilvaStmlNodus* nodus);
SilvaStmlNodus* silva_stml_liberum_ad_indicem(SilvaStmlNodus* nodus,
    unsigned int index);

typedef enum {
    SILVA_ANNOTATIO_SUPRA = 0,   /* supra unitatem sequentem */
    SILVA_ANNOTATIO_INTERIOR,    /* intra unitatem continentem */
    SILVA_ANNOTATIO_PLAGULA      /* scopus plagulae */
} SilvaAnnotatioModus;

typedef struct {
    SilvaChorda textus;          /* corpus purgatum */
    SilvaChorda crudum;          /* octeti pleni delimitatoribus */
    int          fons_index;
    unsigned int linea;          /* 1-basata */
    unsigned int columna;
    int          byte_offset;

    SilvaAnnotatioModus modus;
    const SilvaNodus*   unitas;  /* NIHIL = PLAGULA */

    int              parsata;
    SilvaStmlNodus*  documentum; /* radix documenti */
    SilvaStmlNodus*  arbor;      /* elementum primum; NIHIL fractum */
    SilvaStmlStatus  status;
    unsigned int     linea_erroris;   /* intra textum purgatum */
    unsigned int     columna_erroris;
    SilvaChorda      error;
} SilvaAnnotatio;

/* Xar de SilvaAnnotatio (per valorem), ordo fluminis; intern NIHIL
 * licet. Unitates: Xar de SilvaNodus*, ordo fontis. */
SilvaXar* silva_annotationes_colligere(SilvaPiscina* piscina,
    const SilvaParsura* parsura, SilvaInternamentumChorda* intern);
SilvaXar* silva_annotationes_unitates(SilvaPiscina* piscina,
    const SilvaParsura* parsura);

